use model::*;
use std::collections::BTreeMap;
use std::fmt::Write as _;
use crate::MAX_INPUT;
pub fn escape(text:&str)->String{let mut out=String::new();for c in text.chars(){match c{'\\'|'{'|'}'=>{out.push('\\');out.push(c);},'\n'=>out.push_str("\\line "),'\t'=>out.push_str("\\tab "),'\r'=>{},c if c.is_ascii()&&!c.is_control()=>out.push(c),_=>{let mut buf=[0u16;2];for unit in c.encode_utf16(&mut buf){let _=write!(out,"\\u{}?",*unit as i16);}}}}out}
struct Writer<'a>{doc:&'a Document,out:String,fonts:BTreeMap<String,usize>,colors:BTreeMap<String,usize>}
impl Writer<'_>{
    fn bounded(&self)->Result<(),String>{if self.out.len()>MAX_INPUT{Err("Encoded RTF exceeds 32 MiB".into())}else{Ok(())}}
    fn controls(&mut self,p:&CharacterProperties){self.out.push_str("\\plain");if let Some(f)=&p.font_family{if let Some(i)=self.fonts.get(f){let _=write!(self.out,"\\f{i}");}}if let Some(s)=p.font_size_pt{let _=write!(self.out,"\\fs{}",(s.clamp(1.0,400.0)*2.0).round()as i32);}if let Some(v)=p.bold{self.out.push_str(if v{"\\b"}else{"\\b0"});}if let Some(v)=p.italic{self.out.push_str(if v{"\\i"}else{"\\i0"});}if let Some(v)=p.underline{self.out.push_str(if v{"\\ul"}else{"\\ulnone"});}if let Some(c)=&p.color{if let Some(i)=self.colors.get(c){let _=write!(self.out,"\\cf{i}");}}if let Some(c)=&p.highlight{if c=="none"{self.out.push_str("\\highlight0");}else if let Some(i)=self.colors.get(c){let _=write!(self.out,"\\highlight{i}");}}self.out.push(' ');}
    fn image(&mut self,id:&ResourceId,width:f32,height:f32)->Result<(),String>{let r=self.doc.resources.get(id).ok_or("RTF picture resource missing")?;let tag=match r.media_type.as_str(){"image/png"=>"pngblip","image/jpeg"=>"jpegblip",_=>return Err("RTF writer supports PNG/JPEG only; use a native copy for other images".into())};if !width.is_finite()||!height.is_finite()||width<=0.0||height<=0.0{return Err("Invalid RTF picture size".into());}if r.data.len()>MAX_INPUT/2||self.out.len()+r.data.len()*2>MAX_INPUT{return Err("RTF picture exceeds export size limit".into());}let _=write!(self.out,"{{\\pict\\{tag}\\picwgoal{}\\pichgoal{} ",(width*1440.0/25.4).round()as i32,(height*1440.0/25.4).round()as i32);for b in r.data.iter(){let _=write!(self.out,"{b:02x}");}self.out.push('}');Ok(())}
    fn inlines(&mut self,items:&[Inline],style:Option<&StyleId>,depth:usize)->Result<(),String>{if depth>64{return Err("RTF inline nesting too deep".into());}for item in items{match item{
        Inline::Text(t)=>{self.out.push('{');let p=self.doc.styles.resolve_run(style,t.style.as_ref(),&t.properties);self.controls(&p);self.out.push_str(&escape(&t.text));self.out.push('}');},
        Inline::Hyperlink(h)=>self.inlines(&h.content,style,depth+1)?,Inline::Tab{..}=>self.out.push_str("\\tab "),Inline::PaginationBreak{break_kind,..}=>self.out.push_str(match break_kind{model::PaginationBreakKind::Page=>"\\page ",model::PaginationBreakKind::Column=>"\\column "}),Inline::LineBreak{..}=>self.out.push_str("\\line "),
        Inline::Image(i)=>self.image(&i.resource,i.width_mm,i.height_mm)?,Inline::EmbeddedObject(_)=>return Err("Embedded objects require DOCX or Impress export".into()),Inline::TextBox(_)=>return Err("Text boxes require DOCX or Impress export".into()),Inline::Field(f)=>self.out.push_str(&escape(f.display_text.as_deref().unwrap_or("[Field]"))),Inline::Equation(_)=>return Err("Convert equations explicitly before exporting this RTF subset".into()),
    }self.bounded()?;}Ok(())}
    fn paragraph(&mut self,p:&Paragraph,cell:bool)->Result<(),String>{let props=self.doc.styles.resolve_paragraph_with_direct(p.style.as_ref(),&p.properties);self.out.push_str("\\pard");if cell{self.out.push_str("\\intbl");}self.out.push_str(match props.alignment{Some(ParagraphAlignment::Center)=>"\\qc",Some(ParagraphAlignment::Right)=>"\\qr",Some(ParagraphAlignment::Justify)=>"\\qj",_=>"\\ql"});for(name,value)in[("li",props.left_indent_mm),("ri",props.right_indent_mm),("fi",props.first_line_indent_mm)]{if let Some(v)=value{let _=write!(self.out,"\\{name}{}",(v*1440.0/25.4).round()as i32);}}for(name,value)in[("sb",props.space_before_pt),("sa",props.space_after_pt)]{if let Some(v)=value{let _=write!(self.out,"\\{name}{}",(v*20.0).round()as i32);}}self.out.push(' ');self.inlines(&p.content,p.style.as_ref(),0)?;self.out.push_str("\\par\n");Ok(())}
    fn table(&mut self,t:&Table)->Result<(),String>{for row in &t.rows{self.out.push_str("\\trowd");let mut x=0.0;for(index,c)in row.cells.iter().enumerate(){if c.column_span!=1||c.row_span!=1{return Err("Merged tables require DOCX, HTML or Impress semantic exchange; this RTF adapter refuses to flatten them".into());}let width=t.properties.grid_column_widths_mm.get(index).copied().or(c.width_mm).unwrap_or(30.0);if !width.is_finite()||width<=0.0{return Err("Invalid RTF cell width".into());}x+=width;let _=write!(self.out,"\\cellx{}",(x*1440.0/25.4).round()as i32);}self.out.push('\n');for cell in &row.cells{for b in &cell.blocks{match b{Block::Paragraph(p)=>self.paragraph(p,true)?,_=>return Err("Nested tables/block objects require DOCX or semantic clipboard".into())}}self.out.push_str("\\cell\n");}self.out.push_str("\\row\n");self.bounded()?;}Ok(())}
}
pub fn encode(doc:&Document)->Result<Vec<u8>,String>{
    let mut fonts=BTreeMap::new();let mut colors=BTreeMap::new();fonts.insert("Times New Roman".to_string(),0);
    fn collect(items:&[Inline],style:Option<&StyleId>,doc:&Document,fonts:&mut BTreeMap<String,usize>,colors:&mut BTreeMap<String,usize>,depth:usize)->Result<(),String>{if depth>64{return Err("Excessive inline nesting".into());}for i in items{match i{Inline::Text(t)=>{let p=doc.styles.resolve_run(style,t.style.as_ref(),&t.properties);if let Some(f)=p.font_family{let n=fonts.len();fonts.entry(f).or_insert(n);}for c in [p.color,p.highlight].into_iter().flatten(){if c!="none"{let n=colors.len()+1;colors.entry(c).or_insert(n);}}},Inline::Hyperlink(h)=>collect(&h.content,style,doc,fonts,colors,depth+1)?,_=>{}}}Ok(())}
    for p in document_paragraphs(doc){collect(&p.content,p.style.as_ref(),doc,&mut fonts,&mut colors,0)?;}
    if fonts.len()>4096||colors.len()>4096{return Err("Too many RTF fonts/colors".into());}
    let mut out=String::from("{\\rtf1\\ansi\\ansicpg1252\\deff0\\uc1\n{\\fonttbl");let mut sorted=fonts.iter().collect::<Vec<_>>();sorted.sort_by_key(|(_,id)|**id);for(f,id)in sorted{let _=write!(out,"{{\\f{id}\\fnil\\fcharset0 {};}}",escape(f));}out.push_str("}\n{\\colortbl;");let mut sorted=colors.iter().collect::<Vec<_>>();sorted.sort_by_key(|(_,id)|**id);for(c,_)in sorted{let c=c.trim_start_matches('#');if c.len()!=6||!c.bytes().all(|b|b.is_ascii_hexdigit()){return Err("RTF color must be #RRGGBB".into());}let r=u8::from_str_radix(&c[0..2],16).map_err(|e|e.to_string())?;let g=u8::from_str_radix(&c[2..4],16).map_err(|e|e.to_string())?;let b=u8::from_str_radix(&c[4..6],16).map_err(|e|e.to_string())?;let _=write!(out,"\\red{r}\\green{g}\\blue{b};");}out.push_str("}\n");
    let mut w=Writer{doc,out,fonts,colors};for(index,s)in doc.sections.iter().enumerate(){if index>0{w.out.push_str("\\page\n");}for b in &s.blocks{match b{Block::Paragraph(p)=>w.paragraph(p,false)?,Block::Table(t)=>w.table(t)?,Block::Image(i)=>{w.out.push_str("\\pard ");w.image(&i.resource,i.width_mm,i.height_mm)?;w.out.push_str("\\par\n");},Block::PageBreak{..}=>w.out.push_str("\\page\n"),_=>return Err("An unsupported block cannot be silently removed from RTF output".into())}w.bounded()?;}}w.out.push('}');w.bounded()?;Ok(w.out.into_bytes())
}
